from typing import List, Sequence

def rotate_rota(staff: Sequence[str], n_days: int, per_day: int, first_day: int = 0) -> List[List[str]]:
    if not staff: raise ValueError('staff empty')
    if per_day < 1: raise ValueError('per_day < 1')
    if per_day > len(staff): raise ValueError('per_day > len(staff)')
    if n_days < 0: raise ValueError('n_days < 0')
    if not (0 <= first_day <= 6): raise ValueError('first_day out of range')
    rota = []
    idx = 0
    for _ in range(n_days):
        day = []
        for _ in range(per_day):
            day.append(staff[idx])
            idx = (idx + 1) % len(staff)
        rota.append(day)
    return rota"
  }
}
