from typing import Iterable, List, Tuple


def free_slots(
    busy: Iterable[Tuple[int, int]], start: int, end: int, min_length: int = 0
) -> List[Tuple[int, int]]:
    """
    Find free time slots between `start` and `end` that are not covered by `busy` intervals.
    Only slots with at least `min_length` are returned.
    """
    sorted_busy = sorted(busy)
    free = []
    current = start

    for b_start, b_end in sorted_busy:
        if b_start > current:
            if b_start - current >= min_length:
                free.append((current, b_start))
        current = max(current, b_end)

    if end > current:
        if end - current >= min_length:
            free.append((current, end))

    return free
"}}, "messages": []}
