def rotate_rota(staff: Sequence[str], n_days: int, per_day: int, first_day: int = 0) -> List[List[str]]:
    if not staff: raise ValueError("Staff list cannot be empty")
    if per_day < 1 or per_day > len(staff): raise ValueError("Invalid per_day value")
    if n_days < 0 or not (0 <= first_day <= 6): raise ValueError("Invalid n_days or first_day")

    res = []
    idx = 0
    for day_offset in range(n_days):
        current_day = (first_day + day_offset) % 7
        # Assuming 5 = Saturday, 6 = Sunday
        if current_day == 5 or current_day == 6:
            res.append([])
        else:
            day_staff = []
            for _ in range(per_day):
