from typing import Sequence, Tuple, Mapping, Dict, Optional
from slotplan.intervals import intervals_overlap

def assign_rooms(meetings: Sequence[Tuple[str, int, int, int]], rooms: Mapping[str, int]) -> Dict[str, Optional[str]]:
    # Sort rooms by capacity ascending to facilitate 'smallest room that fits' greedy approach
    sorted_rooms = sorted(rooms.items(), key=lambda x: x[1])

    # Sort meetings: primary = start time (asc), secondary = attendees (desc), tertiary = meeting_id (asc)
    # Meeting tuple: (id, start, end, attendees)
    sorted_meetings = sorted(meetings, key=lambda m: (m[1], -m[3], m[0]))

    assignments: Dict[str, Optional[str]] = {m[0]: None for m in meetings}
    room_occupancy: Dict[str, list[Tuple[int, int]]] = {room_id: [] for room_id in rooms}

    for m_id, start, end, attendees in sorted_meetings:
        for room_id, capacity in sorted_rooms:
            if capacity >= attendees:
                # Check if room is available during the meeting interval
                if not any(intervals_overlap((start, end), existing) for existing in room_occupancy[room_id]):
                    assignments[m_id] = room_id
                    room_occupancy[room_id].append((start, end))
                    break

    return assignments
"}}}
